//
// @ai:generated by=claude-opus-5-5 date=2026-11-05
var ErrProceedingsSchemaFailed = errors.Define("E7001", 500, "Proceedings schema setup failed", "proceedings")

// ProceedingsTables 列出 proceedings schema 應有的資料表。
