// EnsureProceedingsSchema 在單一交易內建立 proceedings 資料表與四個議會的基本資料；可重複執行。
//
// @ai:generated by=claude-opus-5-5 date=2026-11-05
// @ai:purpose 資料收集前先固定結構；全部成功才生效，不會留下半套資料表
// @ai:input ctx, db 資料庫, log
// @ai:output error（ErrProceedingsSchemaFailed）
// @ai:sideeffect 建立 proceedings schema、資料表與索引，寫入 councils
func EnsureProceedingsSchema(ctx context.Context, db *hidb.Database, log *logger.Logger) error {
	err := db.HypDBTransaction(ctx, func(ctx context.Context, tx bun.Tx) error {
		for i, stmt := range proceedingsSchemaStatements {
			if _, err := tx.ExecContext(ctx, stmt); err != nil {
				return fmt.Errorf("statement %d: %w", i+1, err)
			}
		}
		var found int
		if err := tx.NewRaw(`SELECT count(*) FROM pg_tables WHERE schemaname = 'proceedings' AND tablename IN (?)`,
			bun.In(ProceedingsTables)).Scan(ctx, &found); err != nil {
			return fmt.Errorf("verify tables: %w", err)
		}
		if found != len(ProceedingsTables) {
			return fmt.Errorf("found %d of %d tables", found, len(ProceedingsTables))
		}
		return nil
	})
	if err != nil {
		log.Error("setup proceedings schema failed", "err", err)
		return ErrProceedingsSchemaFailed.With("reason", err.Error())
	}
	return nil
}
